import fs from 'node:fs';
import path from 'node:path';
import {buildPlanFixture} from '../scripts/fixtures/user-decision/plan-fixture.mjs';
import {decisionDigest} from '../scripts/lib/user-decision.mjs';
const f=buildPlanFixture(process.cwd());
f.write('plan.md','# Plan 测试数据\n目标：小范围审批细节修订。MVP：既有单笔申请、审批与撤回。非目标：支付、跨组织。\n关键规则：5000元及以上主管审批，审批后不可撤回。验收：5000元主管审批；撤回请求拒绝。\n未决项：空。剩余不确定性：没有执行阻塞。风险：边界金额必须保持测试覆盖。\n下一动作：核验入口后起草 Spec；不授权实现。\n');
for(const item of f.review.basis)item.digest=decisionDigest(fs.readFileSync(item.ref.startsWith('/')?item.ref:path.join(f.root,item.ref)));
f.approval.record.request.items[0].title='共同理解与完整 Plan 合并确认';
f.approval.record.request.items[0].changes='确认目标、MVP、非目标、关键规则、验收例子、未决项结论及剩余不确定性';
f.approval.record.request.items[0].next_actions=['确认共同理解与完整 Plan','入口验证通过后进入 Spec，不授权实现'];
f.reapprove();
for(const reply of f.approval.record.responses)fs.rmSync(reply.source.ref,{force:true});
f.approval.record.responses=[];f.approval.save();f.write('.replay/entry-state.json',f.state);

